    n = len(text)
    for length in range(1, n // 2 + 1):
        if n % length == 0:
            pattern = text[:length]
            valid = True
            for i in range(length, n, length):
                if text[i:i+length] != pattern:
                    valid = False
                    break
            if valid:
                return True
    return False

